import { Prisma } from '../../generated/prisma/client';
import { DateSpan } from './fragments.sql';
import { attributedSalesCte } from './routeSales.sql';

/*
 * Workday comparison of a route (PCRM-188): the route against itself on the
 * same weekday, e.g. this Tuesday's "Zona Escalón" against previous Tuesdays.
 *
 * A workday is a (route, agenda day) pair: the distinct `scheduled_visit.
 * visit_date` of the stops generated by any assignment (`route_user`) of the
 * route. It is read from the agenda the app froze for that day, never
 * regenerated from today's `route_user` / `route_customer`, so a later
 * reassignment does not rewrite the history being compared. `visit_date` is a
 * plain local date, so its ISO weekday matches `route_user.day` (1 Monday …
 * 7 Sunday) with no timezone conversion.
 *
 * Stops on prospects have no customer and are not portfolio (CLAUDE.md 7.1),
 * same rule as the agenda of ./routes.sql.ts.
 */

/** Stops of the route's agenda on or before `today`, aliased `sv` and `ru`. */
const routeAgendaFrom = (routeId: string, today: string): Prisma.Sql => Prisma.sql`
  FROM   scheduled_visit sv
  JOIN   route_user ru
         ON ru.id = sv.route_user_id
  WHERE  sv.deleted_at IS NULL
    AND  sv.customer_id IS NOT NULL
    AND  ru.route_id = ${routeId}::uuid
    AND  sv.visit_date <= ${today}::date
`;

/**
 * The route plus the ISO weekday of its latest workday, the default `day` of
 * the comparison. No row when the route does not exist or is deleted;
 * `latest_day` is null when it never had an agenda.
 */
export const routeWorkdayHeaderSql = (routeId: string, today: string): Prisma.Sql => Prisma.sql`
  SELECT r.id::text AS route_id,
         r.name,
         r.active,
         (SELECT EXTRACT(ISODOW FROM MAX(sv.visit_date))::int
          ${routeAgendaFrom(routeId, today)}) AS latest_day
  FROM   route r
  WHERE  r.id = ${routeId}::uuid
    AND  r.deleted_at IS NULL
`;

/** The latest `limit` workdays of the route on ISO weekday `day`, newest first. */
export const routeWorkdayDatesSql = (
  routeId: string,
  day: number,
  today: string,
  limit: number
): Prisma.Sql => Prisma.sql`
  SELECT DISTINCT sv.visit_date::text AS date
  ${routeAgendaFrom(routeId, today)}
    AND  EXTRACT(ISODOW FROM sv.visit_date) = ${day}
  ORDER  BY date DESC
  LIMIT  ${limit}
`;

/**
 * One row per workday in `dates`, newest first: attributed sale, stops and
 * the rates the comparison reads.
 *
 * `span` bounds the sales by `erp_created_at` (the module's sale date) and
 * covers the first to the last workday; the sale is then credited to the
 * workday of the stop its visit executed, not to the day it was invoiced.
 */
export const routeWorkdayMetricsSql = (
  routeId: string,
  dates: string[],
  span: DateSpan
): Prisma.Sql => Prisma.sql`
  WITH
  ${attributedSalesCte(span)},
  route_sales AS (
    SELECT a.*
    FROM   attributed_sales a
    WHERE  a.route_id = ${routeId}::uuid
      AND  a.visit_date = ANY(${dates}::date[])
  ),
  agenda AS (
    SELECT sv.id,
           sv.visit_date,
           sv.customer_id,
           sv.route_user_id,
           EXISTS (SELECT 1 FROM visit v
                   WHERE v.scheduled_visit_id = sv.id
                     AND v.deleted_at IS NULL)                AS executed,
           EXISTS (SELECT 1 FROM route_sales rs
                   WHERE rs.scheduled_visit_id = sv.id)       AS with_order
    FROM   scheduled_visit sv
    JOIN   route_user ru
           ON ru.id = sv.route_user_id
    WHERE  sv.deleted_at IS NULL
      AND  sv.customer_id IS NOT NULL
      AND  ru.route_id = ${routeId}::uuid
      AND  sv.visit_date = ANY(${dates}::date[])
  ),
  day_stops AS (
    SELECT ag.visit_date,
           COUNT(*)                                                 AS planned_stops,
           COUNT(*) FILTER (WHERE ag.executed)                      AS executed_stops,
           COUNT(*) FILTER (WHERE ag.executed AND ag.with_order)    AS stops_with_order,
           COUNT(DISTINCT ag.customer_id)                           AS planned_customers,
           COUNT(DISTINCT ag.customer_id) FILTER (WHERE ag.executed) AS visited_customers
    FROM   agenda ag
    GROUP  BY ag.visit_date
  ),
  day_sales AS (
    SELECT rs.visit_date,
           SUM(rs.amount)                 AS amount,
           COUNT(DISTINCT rs.erp_sale_id) AS orders_count
    FROM   route_sales rs
    GROUP  BY rs.visit_date
  ),
  day_sellers AS (
    -- Whoever the assignment that generated the day's stops belonged to.
    -- Deleted sellers stay: they still worked that day.
    SELECT d.visit_date,
           json_agg(json_build_object('user_id', d.id::text, 'name', d.name)
                    ORDER BY d.name) AS sellers
    FROM   (SELECT DISTINCT ag.visit_date, u.id, u.name
            FROM   agenda ag
            JOIN   route_user ru
                   ON ru.id = ag.route_user_id
            JOIN   app_user u
                   ON u.id = ru.user_id) d
    GROUP  BY d.visit_date
  )
  SELECT ds.visit_date::text                                   AS date,
         COALESCE(sl.sellers, '[]'::json)                      AS sellers,
         COALESCE(sa.amount, 0)::numeric(14,2)::text           AS amount,
         COALESCE(sa.orders_count, 0)::int                     AS orders_count,
         ds.planned_stops::int                                 AS planned_stops,
         ds.executed_stops::int                                AS executed_stops,
         ds.stops_with_order::int                              AS stops_with_order,
         ROUND(100.0 * ds.visited_customers
               / NULLIF(ds.planned_customers, 0), 1)::float8   AS visit_coverage_rate,
         ROUND(100.0 * ds.stops_with_order
               / NULLIF(ds.executed_stops, 0), 1)::float8      AS order_rate
  FROM   day_stops ds
  LEFT   JOIN day_sales   sa ON sa.visit_date = ds.visit_date
  LEFT   JOIN day_sellers sl ON sl.visit_date = ds.visit_date
  ORDER  BY ds.visit_date DESC
`;
